gameActivityImportAdditions.insert:
import android.media.AudioAttributes;
import android.os.Build;
import android.os.Looper;
import android.os.VibrationEffect;
import android.os.VibrationAttributes;
import android.os.Vibrator;
import android.os.VibratorManager;
import android.provider.Settings;
import android.view.HapticFeedbackConstants;
import android.view.View;
import java.lang.reflect.Method;

gameActivityClassAdditions.insert:
public long[] AndroidThunkJava_OpenMobileHapticsQueryCapabilities()
{
    try
    {
        Vibrator vibrator;
        if (Build.VERSION.SDK_INT >= 31)
        {
            VibratorManager manager =
                (VibratorManager)getSystemService(VIBRATOR_MANAGER_SERVICE);
            if (manager == null)
            {
                return new long[] {-1L};
            }
            vibrator = manager.getDefaultVibrator();
        }
        else
        {
            vibrator = (Vibrator)getSystemService(VIBRATOR_SERVICE);
        }
        if (vibrator == null)
        {
            return new long[] {-1L};
        }
        if (!vibrator.hasVibrator())
        {
            return new long[] {0L, 0L, 0L, -1L, -1L, -1L};
        }

        long flags = 1L | 2L;
        if (Build.VERSION.SDK_INT >= 26)
        {
            flags |= 32L | 64L;
            if (vibrator.hasAmplitudeControl())
            {
                flags |= 8L;
            }
        }
        long presetSupport = 0L;
        long primitiveSupport = 0L;
        long maxControlPoints = -1L;
        long maxDurationMillis = -1L;
        long minTimingMillis = -1L;
        if (Build.VERSION.SDK_INT >= 30)
        {
            int[] effects = vibrator.areEffectsSupported(
                VibrationEffect.EFFECT_TICK,
                VibrationEffect.EFFECT_CLICK,
                VibrationEffect.EFFECT_HEAVY_CLICK,
                VibrationEffect.EFFECT_DOUBLE_CLICK
            );
            for (int index = 0; index < effects.length; ++index)
            {
                presetSupport |= ((long)effects[index] & 3L) << (index * 2);
            }
            flags |= 1024L;
            boolean[] primitives = vibrator.arePrimitivesSupported(
                VibrationEffect.Composition.PRIMITIVE_CLICK,
                VibrationEffect.Composition.PRIMITIVE_THUD,
                VibrationEffect.Composition.PRIMITIVE_SPIN,
                VibrationEffect.Composition.PRIMITIVE_QUICK_RISE,
                VibrationEffect.Composition.PRIMITIVE_SLOW_RISE,
                VibrationEffect.Composition.PRIMITIVE_QUICK_FALL,
                VibrationEffect.Composition.PRIMITIVE_TICK,
                VibrationEffect.Composition.PRIMITIVE_LOW_TICK
            );
            for (int index = 0; index < primitives.length; ++index)
            {
                if (primitives[index])
                {
                    primitiveSupport |= 1L << index;
                }
            }
            flags |= 2048L;
            if (primitiveSupport != 0L)
            {
                flags |= 4L | 128L;
            }
        }
        if (Build.VERSION.SDK_INT >= 36)
        {
            try
            {
                Method envelopeSupportMethod = Vibrator.class.getMethod(
                    "areEnvelopeEffectsSupported"
                );
                boolean envelopeSupported =
                    (Boolean)envelopeSupportMethod.invoke(vibrator);
                flags |= 4096L | 8192L;
                if (envelopeSupported)
                {
                    flags |= 256L;
                    Object envelopeInfo = Vibrator.class.getMethod(
                        "getEnvelopeEffectInfo"
                    ).invoke(vibrator);
                    if (envelopeInfo != null)
                    {
                        maxControlPoints = ((Number)envelopeInfo.getClass()
                            .getMethod("getMaxSize").invoke(envelopeInfo)).longValue();
                        maxDurationMillis = ((Number)envelopeInfo.getClass()
                            .getMethod("getMaxDurationMillis").invoke(envelopeInfo)).longValue();
                        minTimingMillis = ((Number)envelopeInfo.getClass()
                            .getMethod("getMinControlPointDurationMillis")
                            .invoke(envelopeInfo)).longValue();
                    }
                    Object frequencyProfile = Vibrator.class.getMethod(
                        "getFrequencyProfile"
                    ).invoke(vibrator);
                    if (frequencyProfile != null)
                    {
                        flags |= 512L;
                    }
                }
            }
            catch (ReflectiveOperationException exception)
            {
            }
        }
        return new long[] {
            flags,
            presetSupport,
            primitiveSupport,
            maxControlPoints,
            maxDurationMillis,
            minTimingMillis
        };
    }
    catch (Exception exception)
    {
        return new long[] {-1L};
    }
}

public int AndroidThunkJava_OpenMobileHapticsPlaySemantic(
    int behavior,
    float intensity,
    int path,
    int purpose
)
{
    try
    {
        if (path == 1)
        {
            final View view = getWindow() != null
                ? getWindow().getDecorView()
                : null;
            if (view == null || !view.isShown() || !view.hasWindowFocus())
            {
                return 2;
            }
            final int feedback = OpenMobileHapticsFeedbackConstant(behavior);
            if (Looper.myLooper() == Looper.getMainLooper())
            {
                return view.performHapticFeedback(feedback) ? 1 : 2;
            }
            return view.post(new Runnable()
            {
                @Override
                public void run()
                {
                    view.performHapticFeedback(feedback);
                }
            }) ? 1 : 2;
        }

        Vibrator vibrator = OpenMobileHapticsVibrator();
        if (vibrator == null || !vibrator.hasVibrator())
        {
            return 4;
        }
        if (Settings.System.getInt(
                getContentResolver(),
                Settings.System.HAPTIC_FEEDBACK_ENABLED,
                1
            ) == 0)
        {
            return 2;
        }
        VibrationEffect effect = null;
        if (path == 2 && Build.VERSION.SDK_INT >= 29)
        {
            effect = VibrationEffect.createPredefined(
                OpenMobileHapticsPredefinedEffect(behavior)
            );
        }
        long durationMillis = OpenMobileHapticsDurationMillis(behavior);
        if (effect == null && Build.VERSION.SDK_INT >= 26)
        {
            int amplitude = vibrator.hasAmplitudeControl()
                ? Math.max(1, Math.min(255, Math.round(intensity * 255.0f)))
                : VibrationEffect.DEFAULT_AMPLITUDE;
            effect = VibrationEffect.createOneShot(durationMillis, amplitude);
        }
        if (Build.VERSION.SDK_INT >= 33)
        {
            vibrator.vibrate(
                effect,
                VibrationAttributes.createForUsage(
                    OpenMobileHapticsVibrationUsage(purpose)
                )
            );
        }
        else if (Build.VERSION.SDK_INT >= 26)
        {
            vibrator.vibrate(effect, OpenMobileHapticsAudioAttributes(purpose));
        }
        else
        {
            vibrator.vibrate(
                durationMillis,
                OpenMobileHapticsAudioAttributes(purpose)
            );
        }
        return 3;
    }
    catch (SecurityException exception)
    {
        return 0;
    }
    catch (Exception exception)
    {
        return 0;
    }
}

private Vibrator OpenMobileHapticsVibrator()
{
    if (Build.VERSION.SDK_INT >= 31)
    {
        VibratorManager manager =
            (VibratorManager)getSystemService(VIBRATOR_MANAGER_SERVICE);
        return manager != null ? manager.getDefaultVibrator() : null;
    }
    return (Vibrator)getSystemService(VIBRATOR_SERVICE);
}

private int OpenMobileHapticsVibrationUsage(int purpose)
{
    switch (purpose)
    {
        case 1:
            return VibrationAttributes.USAGE_MEDIA;
        case 2:
            return VibrationAttributes.USAGE_NOTIFICATION;
        default:
            return VibrationAttributes.USAGE_TOUCH;
    }
}

private AudioAttributes OpenMobileHapticsAudioAttributes(int purpose)
{
    int usage = AudioAttributes.USAGE_ASSISTANCE_SONIFICATION;
    if (purpose == 1)
    {
        usage = AudioAttributes.USAGE_GAME;
    }
    else if (purpose == 2)
    {
        usage = AudioAttributes.USAGE_NOTIFICATION_EVENT;
    }
    return new AudioAttributes.Builder()
        .setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION)
        .setUsage(usage)
        .build();
}

private int OpenMobileHapticsFeedbackConstant(int behavior)
{
    switch (behavior)
    {
        case 0:
            return Build.VERSION.SDK_INT >= 34
                ? HapticFeedbackConstants.SEGMENT_FREQUENT_TICK
                : HapticFeedbackConstants.CLOCK_TICK;
        case 1:
            return HapticFeedbackConstants.VIRTUAL_KEY;
        case 2:
            return Build.VERSION.SDK_INT >= 23
                ? HapticFeedbackConstants.CONTEXT_CLICK
                : HapticFeedbackConstants.LONG_PRESS;
        case 3:
            return HapticFeedbackConstants.LONG_PRESS;
        case 4:
            return HapticFeedbackConstants.CLOCK_TICK;
        case 5:
            return Build.VERSION.SDK_INT >= 23
                ? HapticFeedbackConstants.CONTEXT_CLICK
                : HapticFeedbackConstants.LONG_PRESS;
        case 6:
            return Build.VERSION.SDK_INT >= 30
                ? HapticFeedbackConstants.CONFIRM
                : HapticFeedbackConstants.VIRTUAL_KEY;
        case 7:
            return Build.VERSION.SDK_INT >= 30
                ? HapticFeedbackConstants.GESTURE_END
                : HapticFeedbackConstants.LONG_PRESS;
        case 8:
        default:
            return Build.VERSION.SDK_INT >= 30
                ? HapticFeedbackConstants.REJECT
                : HapticFeedbackConstants.LONG_PRESS;
    }
}

private int OpenMobileHapticsPredefinedEffect(int behavior)
{
    switch (behavior)
    {
        case 0:
        case 4:
            return VibrationEffect.EFFECT_TICK;
        case 1:
        case 5:
            return VibrationEffect.EFFECT_CLICK;
        case 6:
            return VibrationEffect.EFFECT_DOUBLE_CLICK;
        default:
            return VibrationEffect.EFFECT_HEAVY_CLICK;
    }
}

private long OpenMobileHapticsDurationMillis(int behavior)
{
    switch (behavior)
    {
        case 0:
        case 1:
        case 4:
            return 15L;
        case 2:
        case 5:
            return 25L;
        case 3:
        case 7:
        case 8:
            return 40L;
        case 6:
        default:
            return 30L;
    }
}
